import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import CrowdMonitor from './components/CrowdMonitor';
import DarshanQueue from './components/DarshanQueue';
import StayReservation from './components/StayReservation';
import AmenitiesGrid from './components/AmenitiesGrid';
import ScamRadar from './components/ScamRadar';

export default function App() {
  const [crowd, setCrowd] = useState(null);
  const [darshan, setDarshan] = useState([]);
  const [hotels, setHotels] = useState([]);
  const [amenities, setAmenities] = useState([]);
  const [rates, setRates] = useState([]);
  const [lastPing, setLastPing] = useState("");

  const fetchData = async () => {
    try {
      const [crowdRes, darshanRes, hotelRes, amenitiesRes, ratesRes] = await Promise.all([
        fetch('http://localhost:8000/api/crowd/feed').then(r => r.json()),
        fetch('http://localhost:8000/api/darshan/timings').then(r => r.json()),
        fetch('http://localhost:8000/api/stays/hotels').then(r => r.json()),
        fetch('http://localhost:8000/api/amenities/list').then(r => r.json()),
        fetch('http://localhost:8000/api/scam-radar/rates').then(r => r.json())
      ]);
      setCrowd(crowdRes);
      setDarshan(darshanRes);
      setHotels(hotelRes);
      setAmenities(amenitiesRes);
      setRates(ratesRes);
      setLastPing(new Date().toLocaleTimeString());
    } catch (err) {
      console.error("Fetch failure:", err);
    }
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 4000); // Polls every 4s for live updates
    return () => clearInterval(interval);
  }, []);

  return (
    <div style={{ background: '#f8fafc', minHeight: '100vh', padding: '24px 16px', fontFamily: 'Inter, sans-serif' }}>
      <div style={{ maxWidth: '1200px', margin: '0 auto' }}>

        <Navbar lastPing={lastPing} />

        <CrowdMonitor crowd={crowd} />

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '24px', marginBottom: '24px' }}>
          <DarshanQueue darshan={darshan} />
          <StayReservation hotels={hotels} />
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '24px' }}>
          <AmenitiesGrid amenities={amenities} />
          <ScamRadar rates={rates} />
        </div>

      </div>
    </div>
  );
}
